//! 预设图（新手引导种子）：内置 manifest + 导入时按文件名识别，把预设图的 caption（维度）
//! 与 generation_meta（生成 prompt）原样写回——预设图保留真实库数据，不调 codex（约定 7）。
//! 识别下沉到 ingest_file（所有导入入口的咽喉），任何方式导入预设图都自动还原数据。
//!
//! 14 张预设 = 11 张收集图（source=extension，带反推 caption 维度）+ 3 张生成图
//! （source=codex/bowerbird-cloud，带 generation_meta prompt）。生成图 prompt 的 @引用
//! 指向收集图 filename，预设后 name 保留原 filename → 创作板 @图名 能匹配还原 chip。

use std::path::Path;

use crate::core::library::{Analysis, Asset};
use crate::db::Database;
use crate::error::AppResult;

/// 一张预设图的 manifest 项（数据快照自真实库，原样保留）。
#[derive(Clone)]
pub struct PresetSpec {
    /// resources/samples/<filename>（随包打包 + release_preset_pack 复制到文档目录）。
    pub filename: &'static str,
    /// 写入 assets.name（原库 name；生成图 prompt 的 @引用按它匹配还原 chip）。
    pub display_name: &'static str,
    /// 写入 assets.source（原库 source：extension / codex / bowerbird-cloud）。
    pub source: &'static str,
    /// 写入 assets.generation_session_id（生成图有；收集图 None）。
    pub session_id: Option<&'static str>,
    /// 收集图的反推 caption payload（原样 JSON）；recognize 直接 INSERT analyses(kind=caption)。
    pub caption_payload: Option<&'static str>,
    /// 生成图的 generation_meta payload（原样 JSON，含 prompt/session_id/references）；recognize 直接 INSERT。
    pub generation_meta_payload: Option<&'static str>,
}

