/// 按 file_stem 查 manifest（识别预设图）。用 stem 而非完整文件名，让 webp/png/jpg 都能命中
/// （打包用真实 ext，测试造 png）。
fn manifest_match(filename: &str) -> Option<&'static PresetSpec> {
    let stem = Path::new(filename).file_stem()?.to_str()?;
    PRESET_SPECS
        .iter()
        .find(|s| Path::new(s.filename).file_stem().and_then(|x| x.to_str()) == Some(stem))
}

/// 识别预设图并预填：UPDATE source/name/session_id/origin_path + 覆盖写 caption/generation_meta（最新 manifest payload）。
/// 在 ingest_file 入库后调（含 dedup 命中分支）；命中返回 true。改 manifest 后重导即更新（先删后插）；
/// 普通图不触发 recognize，用户手改的 caption 不受影响。
pub fn recognize_and_prefill(
    db: &Database,
    source_file: &Path,
    asset: &mut Asset,
) -> AppResult<bool> {
    let Some(fname) = source_file.file_name().and_then(|s| s.to_str()) else {
        return Ok(false);
    };
    let Some(spec) = manifest_match(fname) else {
        return Ok(false);
    };

    {
        let conn = db.conn.lock().unwrap();
        // origin_path 一并校正为当前 source：dedup 命中时 existing 的 origin 可能是先入库的
        // 重名文件（如 MoveOut 移回的 hash-ULID 名），校正回规范 preset-XX 路径，让前端能按
        // data-origin 定位到这张预设图（虚拟鼠标引导用）。
        conn.execute(
            "UPDATE assets SET source=?1, name=?2, generation_session_id=?3, origin_path=?4 WHERE id=?5",
            rusqlite::params![
                spec.source,
                spec.display_name,
                spec.session_id,
                source_file.to_string_lossy(),
                asset.id
            ],
        )?;
        // 预设图 analysis 用最新 manifest payload 覆盖（先删后插）：改 manifest 后重导即更新；
        // 普通图不触发 recognize，用户手改的 caption 不受影响。
        if spec.caption_payload.is_some() {
            conn.execute(
                "DELETE FROM analyses WHERE asset_id=?1 AND kind='caption'",
                rusqlite::params![asset.id],
            )?;
        }
        if spec.generation_meta_payload.is_some() {
            conn.execute(
                "DELETE FROM analyses WHERE asset_id=?1 AND kind='generation_meta'",
                rusqlite::params![asset.id],
            )?;
        }
    }
    asset.source = Some(spec.source.to_string());
    asset.name = spec.display_name.to_string();
    asset.generation_session_id = spec.session_id.map(|s| s.to_string());
    asset.origin_path = Some(source_file.to_string_lossy().into_owned());

    if let Some(payload) = spec.caption_payload {
        db.insert_analysis(&Analysis {
            id: ulid::Ulid::new().to_string(),
            asset_id: asset.id.clone(),
            kind: "caption".to_string(),
            payload: payload.to_string(),
            provider: Some(spec.source.to_string()),
            created_at: None,
        })?;
    }
    if let Some(payload) = spec.generation_meta_payload {
        db.insert_analysis(&Analysis {
            id: ulid::Ulid::new().to_string(),
            asset_id: asset.id.clone(),
            kind: "generation_meta".to_string(),
            payload: payload.to_string(),
            provider: Some(spec.source.to_string()),
            created_at: None,
        })?;
    }
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::ingest::ingest_file;
    use crate::core::paths::LibraryPaths;
    use crate::db::Database;
    use crate::media::phash::testutil::make_photo_file;
    use std::path::PathBuf;
    use ulid::Ulid;

    struct Tmp {
        dir: PathBuf,
    }
    impl Drop for Tmp {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.dir);
        }
    }

    fn setup() -> (Tmp, LibraryPaths, Database) {
        let dir = std::env::temp_dir().join(format!("bb-preset-{}", Ulid::new()));
        std::fs::create_dir_all(&dir).unwrap();
        let paths = LibraryPaths::init(dir.clone()).unwrap();
        let db = Database::open_in_memory().unwrap();
        db.migrate().unwrap();
        (Tmp { dir }, paths, db)
    }

    #[test]
    fn manifest_match_by_stem_across_extensions() {
        assert!(manifest_match("preset-01.webp").is_some());
        assert!(manifest_match("preset-01.png").is_some());
        assert!(manifest_match("preset-12.png").is_some());
        assert!(manifest_match("my-photo.png").is_none());
    }

    /// 收集图（preset-01）：source=extension + caption + 无 generation_meta + 无 session_id。
    #[test]
    fn ingest_preset_collect_writes_caption_no_meta() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "preset-01.png", 256, 1);
        let asset = ingest_file(&paths, &db, &img).unwrap();
        let spec = manifest_match("preset-01.png").unwrap();
        assert_eq!(asset.source.as_deref(), Some(spec.source));
        assert_eq!(asset.name, spec.display_name);
        assert!(asset.generation_session_id.is_none());
        assert!(db.has_analysis(&asset.id, "caption").unwrap());
        assert!(!db.has_analysis(&asset.id, "generation_meta").unwrap());
    }

    /// 生成图（preset-12）：有 session_id + generation_meta。
    #[test]
    fn ingest_preset_generated_writes_meta_and_session() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "preset-12.png", 256, 2);
        let asset = ingest_file(&paths, &db, &img).unwrap();
        let spec = manifest_match("preset-12.png").unwrap();
        assert!(spec.session_id.is_some());
        assert!(spec.generation_meta_payload.is_some());
        assert_eq!(asset.generation_session_id.as_deref(), spec.session_id);
        assert!(db.has_analysis(&asset.id, "generation_meta").unwrap());
    }

    /// 普通文件名不识别：source=imported，无 caption / generation_meta。
    #[test]
    fn ingest_normal_filename_not_recognized() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "my-photo.png", 256, 3);
        let asset = ingest_file(&paths, &db, &img).unwrap();
        assert_eq!(asset.source.as_deref(), Some("imported"));
        assert!(!db.has_analysis(&asset.id, "caption").unwrap());
        assert!(!db.has_analysis(&asset.id, "generation_meta").unwrap());
    }

    /// 二次导入同图（phash dedup 命中）→ 不重复写 caption。
    #[test]
    fn ingest_preset_idempotent_after_dedup() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "preset-01.png", 256, 4);
        let _ = ingest_file(&paths, &db, &img).unwrap();
        let second = ingest_file(&paths, &db, &img).unwrap();
        let count: i64 = db
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM analyses WHERE asset_id=?1 AND kind='caption'",
                rusqlite::params![second.id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(count, 1, "重复导入不应新增 caption");
    }

    /// 生成图预填后 generation_history 能重建 turns（复用回路验证）。
    #[test]
    fn generation_history_roundtrip_for_generated_preset() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "preset-12.png", 256, 5);
        let asset = ingest_file(&paths, &db, &img).unwrap();
        let hist = db.generation_history(&asset.id, None, None).unwrap();
        assert_eq!(hist.turns.len(), 1);
    }

    /// 同一张图先以非预设名入库（如重复文件 hash 名先被遍历）、再以 preset 名导入 →
    /// phash dedup 命中返回 existing，且识别应补上 caption / source（dedup 分支也走 recognize）。
    #[test]
    fn ingest_preset_dedup_repairs_when_alias_first() {
        let (tmp, paths, db) = setup();
        let img = make_photo_file(&tmp.dir, "preset-01.png", 256, 6);
        // 第一步：hash 名先导入 → 无 caption、source=imported。
        let alias = tmp.dir.join("94f8bdba-alias.png");
        std::fs::copy(&img, &alias).unwrap();
        let first = ingest_file(&paths, &db, &alias).unwrap();
        assert!(!db.has_analysis(&first.id, "caption").unwrap());
        assert_eq!(first.source.as_deref(), Some("imported"));
        // 第二步：preset 名导入同一图 → dedup 命中 existing → 识别补上。
        let second = ingest_file(&paths, &db, &img).unwrap();
        assert_eq!(first.id, second.id, "dedup 应返回同一 asset");
        assert!(
            db.has_analysis(&second.id, "caption").unwrap(),
            "dedup 命中后应补 caption"
        );
        assert_eq!(second.source.as_deref(), Some("extension"));
    }
}
